describe('Benutzerverwaltung Dokumentation', () => {
  // Zielordner für diesen Workflow definieren (relativ zu docs/)
  Cypress.env('docu_target_dir', 'Administration/bilder/screenshots');

  it('erstellt Screenshot der Benutzer-Übersicht (R1 - Gesamtübersicht)', () => {
    cy.login('r1')
    cy.visit('administration/benutzerverwaltung')

    cy.get('ul.dienststellen-liste').within(() => {
      cy.get('> li').then(($lis) => {
        if ($lis.length > 2) { $lis.slice(2).hide() }
      })
      cy.get('> li').each(($ressort) => {
        cy.wrap($ressort).find('> ul > li').then(($bereiche) => {
          if ($bereiche.length > 5) { $bereiche.slice(5).hide() }
        })
      })
    })

    cy.get('main').docuScreenshot('01-benutzer-uebersicht-r1')
